(function(w){w.HOMEWORK_SET_DATA=w.HOMEWORK_SET_DATA||{};w.HOMEWORK_SET_DATA["unit22-l11-quick-basic"]={"id":"unit22-l11-quick-basic","unitId":"2-2","chapterIds":["2-2"],"unitType":"basic","group":"2-2단원 · 3. 시장 대 줄 서기","name":"11문단 · 차근차근 핵심 OX","level":"기본","desc":"짧은 사실을 여러 표현으로 비교하고, 마지막에는 문단의 핵심 뜻을 확인해요.","revision":3,"originPage":"unit22","shuffleQuestions":false,"timedMode":"question","readingBlock":"challenge","readingChunk":"p11-12","isQuickPractice":true,"parts":[{"name":"1단계 · 핵심 낱말과 사실","items":[{"id":"U22-H11-01-B1","type":"ox","changed":"글쓴이는 자유 시장 옹호자들이 할 법한 말을 예상해 소개한다.","answer":"O","ask":"형광펜 문장을 읽고, 다음 설명이 맞으면 O, 틀리면 X를 고르세요.","why":"“반응을 보일 수 있다”는 말은 앞으로 나올 수 있는 반론을 미리 생각해 본다는 뜻이에요. 실제로 한 말을 그대로 옮긴 것이 아닙니다.\n근거: “이러한 주장에 대해 자유 시장 옹호자들은 다음과 같은 반응을 보일 수 있다.”","paragraphCount":1,"readingLabel":"11문단 · 핵심 읽기 1/5단계","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 11문단","passage":"[핵심 문장 · 11문단]\n이러한 주장에 대해 자유 시장 옹호자들은 다음과 같은 반응을 보일 수 있다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"highlightEvidence":true,"originPage":"unit22","shortComparison":true,"focusQuotes":[{"id":"L11:1","text":"이러한 주장에 대해 자유 시장 옹호자들은 다음과 같은 반응을 보일 수 있다."}],"skills":["주체"],"evidence":{"title":"시장 지지자들의 예상 답변","statement":"글쓴이는 자유 시장 옹호자들이 할 법한 말을 예상해 소개한다.","explanation":"“반응을 보일 수 있다”는 말은 앞으로 나올 수 있는 반론을 미리 생각해 본다는 뜻이에요. 실제로 한 말을 그대로 옮긴 것이 아닙니다.\n근거: “이러한 주장에 대해 자유 시장 옹호자들은 다음과 같은 반응을 보일 수 있다.”","valid":["L11:1"],"sources":[{"id":"L11","title":"줄 서기를 돈으로 살 수 있을까","label":"11문단","sentences":[{"id":"L11:1","text":"이러한 주장에 대해 자유 시장 옹호자들은 다음과 같은 반응을 보일 수 있다.","paragraph":0,"memberIds":["L11:1"],"topic":"“이러한 주장”은 앞 문단의 “암표 거래는 돈이 부족한 사람에게 불공정하다”는 주장이다. 이에 대해 자유 시장 옹호자들이 아래처럼 반론할 수 있다고 필자가 예상한다."}]}]},"progressiveComparison":true,"progressiveStep":1,"progressiveTotal":5,"progressiveLabel":"핵심 낱말과 사실","learningFocus":"시장 지지자들의 예상 답변","hintGuide":"첫 문장의 “보일 수 있다”가 무슨 뜻인지 생각해 보세요.","synthesis":false,"editorSourceVersion":"a481e5c69edbc8117deb11ccf377781db70e3ce662ba34441e3a5a2aee046ef6"},{"id":"U22-H11-01-B2","type":"ox","changed":"시장을 지지하는 사람들은 표값을 가장 적게 내는 사람이 공연을 가장 보고 싶어 한다고 본다.","answer":"X","ask":"형광펜 문장을 읽고, 다음 설명이 맞으면 O, 틀리면 X를 고르세요.","why":"시장 옹호자들은 가장 비싼 값을 내는 사람이 공연을 가장 높게 평가한다고 생각해요. “적게”를 “많이”로 고쳐야 합니다.\n근거: “그런데 그 사람은 바로 입장권에 최고 가격을 지불하는 사람들이다.”","paragraphCount":1,"readingLabel":"11문단 · 핵심 읽기 1/5단계","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 11문단","passage":"[핵심 문장 · 11문단]\n그런데 그 사람은 바로 입장권에 최고 가격을 지불하는 사람들이다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"highlightEvidence":true,"originPage":"unit22","shortComparison":true,"focusQuotes":[{"id":"L11:3","text":"그런데 그 사람은 바로 입장권에 최고 가격을 지불하는 사람들이다."}],"skills":["반의어"],"evidence":{"title":"평가 기준","statement":"시장을 지지하는 사람들은 표값을 가장 많이 내는 사람이 공연을 가장 보고 싶어 한다고 본다.","explanation":"시장 옹호자들은 가장 비싼 값을 내는 사람이 공연을 가장 높게 평가한다고 생각해요. “적게”를 “많이”로 고쳐야 합니다.\n근거: “그런데 그 사람은 바로 입장권에 최고 가격을 지불하는 사람들이다.”","valid":["L11:3"],"sources":[{"id":"L11","title":"줄 서기를 돈으로 살 수 있을까","label":"11문단","sentences":[{"id":"L11:3","text":"그런데 그 사람은 바로 입장권에 최고 가격을 지불하는 사람들이다.","paragraph":0,"memberIds":["L11:3"],"topic":"\"그 사람이 누구냐고? 바로 표에 가장 비싼 돈을 내는 사람이야.\""}]}]},"claimEdits":[{"start":21,"end":24,"before":"적게 ","after":"많이 "}],"progressiveComparison":true,"progressiveStep":1,"progressiveTotal":5,"progressiveLabel":"핵심 낱말과 사실","learningFocus":"평가 기준","hintGuide":"시장 옹호자들은 돈을 적게 내는 사람과 많이 내는 사람 중 누구를 고르나요?","synthesis":false,"editorSourceVersion":"26763e5b16db00e90ec4417b35dd7baa31aa0454a488ce000a621219f690742c"}]},{"name":"2단계 · 표현 바꿔 읽기","items":[{"id":"U22-H11-02-B1","type":"ox","changed":"즐거움을 “극대화한다”는 말은 관객이 공연에서 느끼는 즐거움을 최대한 크게 한다는 뜻이다.","answer":"O","ask":"형광펜 문장을 읽고, 다음 설명이 맞으면 O, 틀리면 X를 고르세요.","why":"극대화는 최대한 크게 한다는 뜻이에요. 여기서는 관객이 공연을 보며 느끼는 즐거움을 말합니다.\n근거: “극장 측이 연극을 열렬하게 관람하고 싶어 하는 사람들로 관람석을 채우고 공연이 주는 즐거움을 극대화하고 싶다면, 그 가치를 가장 높게 평가하는 사람에게 입장권이 돌아가기를 원해야 한다.”","paragraphCount":1,"readingLabel":"11문단 · 핵심 읽기 2/5단계","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 11문단","passage":"[핵심 문장 · 11문단]\n극장 측이 연극을 열렬하게 관람하고 싶어 하는 사람들로 관람석을 채우고 공연이 주는 즐거움을 극대화하고 싶다면, 그 가치를 가장 높게 평가하는 사람에게 입장권이 돌아가기를 원해야 한다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"highlightEvidence":true,"originPage":"unit22","shortComparison":true,"focusQuotes":[{"id":"L11:2","text":"극장 측이 연극을 열렬하게 관람하고 싶어 하는 사람들로 관람석을 채우고 공연이 주는 즐거움을 극대화하고 싶다면, 그 가치를 가장 높게 평가하는 사람에게 입장권이 돌아가기를 원해야 한다."}],"skills":["비교"],"evidence":{"title":"극대화의 뜻","statement":"즐거움을 “극대화한다”는 말은 관객이 공연에서 느끼는 즐거움을 최대한 크게 한다는 뜻이다.","explanation":"극대화는 최대한 크게 한다는 뜻이에요. 여기서는 관객이 공연을 보며 느끼는 즐거움을 말합니다.\n근거: “극장 측이 연극을 열렬하게 관람하고 싶어 하는 사람들로 관람석을 채우고 공연이 주는 즐거움을 극대화하고 싶다면, 그 가치를 가장 높게 평가하는 사람에게 입장권이 돌아가기를 원해야 한다.”","valid":["L11:2"],"sources":[{"id":"L11","title":"줄 서기를 돈으로 살 수 있을까","label":"11문단","sentences":[{"id":"L11:2","text":"극장 측이 연극을 열렬하게 관람하고 싶어 하는 사람들로 관람석을 채우고 공연이 주는 즐거움을 극대화하고 싶다면, 그 가치를 가장 높게 평가하는 사람에게 입장권이 돌아가기를 원해야 한다.","paragraph":0,"memberIds":["L11:2"],"topic":"\"극장은 정말 보고 싶은 사람들로 자리를 채우고 싶지? 공연의 즐거움을 최대로 하고 싶지? 그렇다면 공연을 가장 귀하게 여기는 사람에게 표가 가야 해.\""}]}]},"progressiveComparison":true,"progressiveStep":2,"progressiveTotal":5,"progressiveLabel":"표현 바꿔 읽기","learningFocus":"극대화의 뜻","hintGuide":"“극대화”를 “최대한 크게 하기”로 바꿔 읽어 보세요.","synthesis":false,"editorSourceVersion":"4f9e3b7f42a86951cf27770b9a64e2c44e3d2dd35aac9398c5c6e2ae045e8587"},{"id":"U22-H11-02-B2","type":"ox","changed":"표를 팔도록 “허용한다”는 말은 표를 팔지 못하게 막는다는 뜻이다.","answer":"X","ask":"형광펜 문장을 읽고, 다음 설명이 맞으면 O, 틀리면 X를 고르세요.","why":"허용은 어떤 일을 할 수 있게 해 주는 것이에요. 팔지 못하게 막는 것은 금지입니다.\n근거: “다시 말해 시장이 수용할 수 있는 가격이 얼마가 됐든 그 가격에 입장권을 판매하든지, 아니면 돈을 받고 대신 줄을 선 사람이나 암표상이 가장 높은 가격을 지불하려는 사람에게 입장권을 팔 수 있도록 허용하는 것이다.”","paragraphCount":1,"readingLabel":"11문단 · 핵심 읽기 2/5단계","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 11문단","passage":"[핵심 문장 · 11문단]\n다시 말해 시장이 수용할 수 있는 가격이 얼마가 됐든 그 가격에 입장권을 판매하든지, 아니면 돈을 받고 대신 줄을 선 사람이나 암표상이 가장 높은 가격을 지불하려는 사람에게 입장권을 팔 수 있도록 허용하는 것이다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"highlightEvidence":true,"originPage":"unit22","shortComparison":true,"focusQuotes":[{"id":"L11:5","text":"다시 말해 시장이 수용할 수 있는 가격이 얼마가 됐든 그 가격에 입장권을 판매하든지, 아니면 돈을 받고 대신 줄을 선 사람이나 암표상이 가장 높은 가격을 지불하려는 사람에게 입장권을 팔 수 있도록 허용하는 것이다."}],"skills":["반의어"],"evidence":{"title":"허용의 뜻","statement":"표를 팔도록 “허용한다”는 말은 표를 팔 수 있게 해 준다는 뜻이다.","explanation":"허용은 어떤 일을 할 수 있게 해 주는 것이에요. 팔지 못하게 막는 것은 금지입니다.\n근거: “다시 말해 시장이 수용할 수 있는 가격이 얼마가 됐든 그 가격에 입장권을 판매하든지, 아니면 돈을 받고 대신 줄을 선 사람이나 암표상이 가장 높은 가격을 지불하려는 사람에게 입장권을 팔 수 있도록 허용하는 것이다.”","valid":["L11:5"],"sources":[{"id":"L11","title":"줄 서기를 돈으로 살 수 있을까","label":"11문단","sentences":[{"id":"L11:5","text":"다시 말해 시장이 수용할 수 있는 가격이 얼마가 됐든 그 가격에 입장권을 판매하든지, 아니면 돈을 받고 대신 줄을 선 사람이나 암표상이 가장 높은 가격을 지불하려는 사람에게 입장권을 팔 수 있도록 허용하는 것이다.","paragraph":0,"memberIds":["L11:5"],"topic":"\"방법은 두 가지야. ㉠ 극장이 사람들이 낼 수 있는 만큼 값을 매겨 표를 팔거나, ㉡ 줄 알바나 암표상이 가장 비싸게 사려는 사람에게 팔게 내버려 두거나.\""}]}]},"claimEdits":[{"start":21,"end":33,"before":"팔지 못하게 막는다는 ","after":"팔 수 있게 해 준다는 "}],"progressiveComparison":true,"progressiveStep":2,"progressiveTotal":5,"progressiveLabel":"표현 바꿔 읽기","learningFocus":"허용의 뜻","hintGuide":"허용과 금지는 같은 뜻인가요?","synthesis":false,"editorSourceVersion":"03320095af091389ea8f3631b836eb86423e897cadab98c5f738dc8e9908f7b9"}]},{"name":"3단계 · 정보 구별","items":[{"id":"U22-H11-03-B1","type":"ox","changed":"시장 옹호자들은 극장이 직접 표를 팔게 하자고 제안할 수 있다.","answer":"O","ask":"형광펜 문장을 읽고, 다음 설명이 맞으면 O, 틀리면 X를 고르세요.","why":"예상 반론에는 극장이 직접 표를 파는 방법이 나와요. 대리 줄 서기나 암표 판매를 허용하는 방법도 함께 소개합니다.\n근거: “다시 말해 시장이 수용할 수 있는 가격이 얼마가 됐든 그 가격에 입장권을 판매하든지, 아니면 돈을 받고 대신 줄을 선 사람이나 암표상이 가장 높은 가격을 지불하려는 사람에게 입장권을 팔 수 있도록 허용하는 것이다.”","paragraphCount":1,"readingLabel":"11문단 · 핵심 읽기 3/5단계","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 11문단","passage":"[핵심 문장 · 11문단]\n다시 말해 시장이 수용할 수 있는 가격이 얼마가 됐든 그 가격에 입장권을 판매하든지, 아니면 돈을 받고 대신 줄을 선 사람이나 암표상이 가장 높은 가격을 지불하려는 사람에게 입장권을 팔 수 있도록 허용하는 것이다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"highlightEvidence":true,"originPage":"unit22","shortComparison":true,"focusQuotes":[{"id":"L11:5","text":"다시 말해 시장이 수용할 수 있는 가격이 얼마가 됐든 그 가격에 입장권을 판매하든지, 아니면 돈을 받고 대신 줄을 선 사람이나 암표상이 가장 높은 가격을 지불하려는 사람에게 입장권을 팔 수 있도록 허용하는 것이다."}],"skills":["비교"],"evidence":{"title":"표를 파는 두 방법","statement":"시장 옹호자들은 극장이 직접 표를 팔게 하자고 제안할 수 있다.","explanation":"예상 반론에는 극장이 직접 표를 파는 방법이 나와요. 대리 줄 서기나 암표 판매를 허용하는 방법도 함께 소개합니다.\n근거: “다시 말해 시장이 수용할 수 있는 가격이 얼마가 됐든 그 가격에 입장권을 판매하든지, 아니면 돈을 받고 대신 줄을 선 사람이나 암표상이 가장 높은 가격을 지불하려는 사람에게 입장권을 팔 수 있도록 허용하는 것이다.”","valid":["L11:5"],"sources":[{"id":"L11","title":"줄 서기를 돈으로 살 수 있을까","label":"11문단","sentences":[{"id":"L11:5","text":"다시 말해 시장이 수용할 수 있는 가격이 얼마가 됐든 그 가격에 입장권을 판매하든지, 아니면 돈을 받고 대신 줄을 선 사람이나 암표상이 가장 높은 가격을 지불하려는 사람에게 입장권을 팔 수 있도록 허용하는 것이다.","paragraph":0,"memberIds":["L11:5"],"topic":"\"방법은 두 가지야. ㉠ 극장이 사람들이 낼 수 있는 만큼 값을 매겨 표를 팔거나, ㉡ 줄 알바나 암표상이 가장 비싸게 사려는 사람에게 팔게 내버려 두거나.\""}]}]},"progressiveComparison":true,"progressiveStep":3,"progressiveTotal":5,"progressiveLabel":"정보 구별","learningFocus":"표를 파는 두 방법","hintGuide":"“입장권을 판매하든지”와 “아니면”으로 나뉜 두 방법을 보세요.","synthesis":false,"editorSourceVersion":"b0a489dd2ef89f1da3e3888ac5307ded71b4efe9d43a5f341eff087427e5981c"},{"id":"U22-H11-03-B2","type":"ox","changed":"시장을 지지하는 사람들은 오래 기다린 사람일수록 공연을 더 보고 싶어 한다고 본다.","answer":"X","ask":"형광펜 문장을 읽고, 다음 설명이 맞으면 O, 틀리면 X를 고르세요.","why":"시장 옹호자들이 보는 것은 기다린 시간이 아니에요. 표를 사려고 돈을 얼마나 많이 내겠다고 하는지를 보고, 누가 공연을 가장 원하는지 판단합니다.\n근거: “최고 가격을 자발적으로 지불하는 사람에게 입장권이 돌아가게 하는 것이 셰익스피어 공연의 가치를 가장 높게 평가하는 사람을 결정하는 최고의 방법이다.”","paragraphCount":1,"readingLabel":"11문단 · 핵심 읽기 3/5단계","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 11문단","passage":"[핵심 문장 · 11문단]\n최고 가격을 자발적으로 지불하는 사람에게 입장권이 돌아가게 하는 것이 셰익스피어 공연의 가치를 가장 높게 평가하는 사람을 결정하는 최고의 방법이다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"highlightEvidence":true,"originPage":"unit22","shortComparison":true,"focusQuotes":[{"id":"L11:6","text":"최고 가격을 자발적으로 지불하는 사람에게 입장권이 돌아가게 하는 것이 셰익스피어 공연의 가치를 가장 높게 평가하는 사람을 결정하는 최고의 방법이다."}],"skills":["비교"],"evidence":{"title":"시간과 가격 구별","statement":"시장을 지지하는 사람들은 돈을 많이 내겠다는 사람일수록 공연을 더 보고 싶어 한다고 본다.","explanation":"시장 옹호자들이 보는 것은 기다린 시간이 아니에요. 표를 사려고 돈을 얼마나 많이 내겠다고 하는지를 보고, 누가 공연을 가장 원하는지 판단합니다.\n근거: “최고 가격을 자발적으로 지불하는 사람에게 입장권이 돌아가게 하는 것이 셰익스피어 공연의 가치를 가장 높게 평가하는 사람을 결정하는 최고의 방법이다.”","valid":["L11:6"],"sources":[{"id":"L11","title":"줄 서기를 돈으로 살 수 있을까","label":"11문단","sentences":[{"id":"L11:6","text":"최고 가격을 자발적으로 지불하는 사람에게 입장권이 돌아가게 하는 것이 셰익스피어 공연의 가치를 가장 높게 평가하는 사람을 결정하는 최고의 방법이다.","paragraph":0,"memberIds":["L11:6"],"topic":"\"스스로 가장 비싼 돈을 내는 사람에게 표를 주는 것, 그게 공연을 가장 좋아하는 사람을 고르는 최고의 방법이야.\""}]}]},"claimEdits":[{"start":14,"end":21,"before":"오래 기다린 ","after":"돈을 많이 내겠다는 "}],"progressiveComparison":true,"progressiveStep":3,"progressiveTotal":5,"progressiveLabel":"정보 구별","learningFocus":"시간과 가격 구별","hintGuide":"마지막 문장에서 사람을 고를 때 보는 것이 시간인지, 가격인지 찾아보세요.","synthesis":false,"editorSourceVersion":"9a5da5f9cc14dc02ea068dd747809f55cbfe451bae08498d45865d39c6dc8309"}]},{"name":"4단계 · 관계 파악","items":[{"id":"U22-H11-04-B1","type":"ox","changed":"시장 옹호자들은 암표상도 가장 비싼 값을 내겠다는 사람에게 표를 팔 수 있게 하자고 말할 수 있다.","answer":"O","ask":"형광펜 문장을 읽고, 다음 설명이 맞으면 O, 틀리면 X를 고르세요.","why":"예상 반론에는 암표 판매를 허용하는 방법이 있어요. 암표상이 가장 높은 가격을 내겠다는 사람에게 표를 팔게 하자는 것입니다.\n근거: “다시 말해 시장이 수용할 수 있는 가격이 얼마가 됐든 그 가격에 입장권을 판매하든지, 아니면 돈을 받고 대신 줄을 선 사람이나 암표상이 가장 높은 가격을 지불하려는 사람에게 입장권을 팔 수 있도록 허용하는 것이다.”","paragraphCount":1,"readingLabel":"11문단 · 핵심 읽기 4/5단계","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 11문단","passage":"[핵심 문장 · 11문단]\n다시 말해 시장이 수용할 수 있는 가격이 얼마가 됐든 그 가격에 입장권을 판매하든지, 아니면 돈을 받고 대신 줄을 선 사람이나 암표상이 가장 높은 가격을 지불하려는 사람에게 입장권을 팔 수 있도록 허용하는 것이다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"highlightEvidence":true,"originPage":"unit22","shortComparison":true,"focusQuotes":[{"id":"L11:5","text":"다시 말해 시장이 수용할 수 있는 가격이 얼마가 됐든 그 가격에 입장권을 판매하든지, 아니면 돈을 받고 대신 줄을 선 사람이나 암표상이 가장 높은 가격을 지불하려는 사람에게 입장권을 팔 수 있도록 허용하는 것이다."}],"skills":["인과"],"evidence":{"title":"표를 팔게 하자는 이유","statement":"시장 옹호자들은 암표상도 가장 비싼 값을 내겠다는 사람에게 표를 팔 수 있게 하자고 말할 수 있다.","explanation":"예상 반론에는 암표 판매를 허용하는 방법이 있어요. 암표상이 가장 높은 가격을 내겠다는 사람에게 표를 팔게 하자는 것입니다.\n근거: “다시 말해 시장이 수용할 수 있는 가격이 얼마가 됐든 그 가격에 입장권을 판매하든지, 아니면 돈을 받고 대신 줄을 선 사람이나 암표상이 가장 높은 가격을 지불하려는 사람에게 입장권을 팔 수 있도록 허용하는 것이다.”","valid":["L11:5"],"sources":[{"id":"L11","title":"줄 서기를 돈으로 살 수 있을까","label":"11문단","sentences":[{"id":"L11:5","text":"다시 말해 시장이 수용할 수 있는 가격이 얼마가 됐든 그 가격에 입장권을 판매하든지, 아니면 돈을 받고 대신 줄을 선 사람이나 암표상이 가장 높은 가격을 지불하려는 사람에게 입장권을 팔 수 있도록 허용하는 것이다.","paragraph":0,"memberIds":["L11:5"],"topic":"\"방법은 두 가지야. ㉠ 극장이 사람들이 낼 수 있는 만큼 값을 매겨 표를 팔거나, ㉡ 줄 알바나 암표상이 가장 비싸게 사려는 사람에게 팔게 내버려 두거나.\""}]}]},"progressiveComparison":true,"progressiveStep":4,"progressiveTotal":5,"progressiveLabel":"관계 파악","learningFocus":"표를 팔게 하자는 이유","hintGuide":"암표상이 표를 누구에게 팔 수 있도록 하자는지 보세요.","synthesis":false,"editorSourceVersion":"53188fe614f2102cdc2c463312c9b0a7093c9f68602948b248fb7c0665f6e94e"},{"id":"U22-H11-04-B2","type":"ox","changed":"시장을 지지하는 사람들은 표를 파는 것보다 선착순으로 나눠 주는 편이 더 낫다고 본다.","answer":"X","ask":"형광펜 문장을 읽고, 다음 설명이 맞으면 O, 틀리면 X를 고르세요.","why":"예상 반론에서는 표를 자유 시장에 맡기는 것이 최선이라고 해요. 선착순으로 나눠 주자는 주장이 아닙니다.\n근거: “따라서 공연에서 최대의 즐거움을 끌어낼 관객으로 극장을 채울 수 있는 최선의 방법은 입장권을 자유 시장에 맡기는 것이다.”","paragraphCount":1,"readingLabel":"11문단 · 핵심 읽기 4/5단계","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 11문단","passage":"[핵심 문장 · 11문단]\n따라서 공연에서 최대의 즐거움을 끌어낼 관객으로 극장을 채울 수 있는 최선의 방법은 입장권을 자유 시장에 맡기는 것이다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"highlightEvidence":true,"originPage":"unit22","shortComparison":true,"focusQuotes":[{"id":"L11:4","text":"따라서 공연에서 최대의 즐거움을 끌어낼 관객으로 극장을 채울 수 있는 최선의 방법은 입장권을 자유 시장에 맡기는 것이다."}],"skills":["인과"],"evidence":{"title":"높은 가격에 팔자는 이유","statement":"시장을 지지하는 사람들은 표를 선착순으로 나눠 주는 것보다 시장에서 파는 편이 더 낫다고 본다.","explanation":"예상 반론에서는 표를 자유 시장에 맡기는 것이 최선이라고 해요. 선착순으로 나눠 주자는 주장이 아닙니다.\n근거: “따라서 공연에서 최대의 즐거움을 끌어낼 관객으로 극장을 채울 수 있는 최선의 방법은 입장권을 자유 시장에 맡기는 것이다.”","valid":["L11:4"],"sources":[{"id":"L11","title":"줄 서기를 돈으로 살 수 있을까","label":"11문단","sentences":[{"id":"L11:4","text":"따라서 공연에서 최대의 즐거움을 끌어낼 관객으로 극장을 채울 수 있는 최선의 방법은 입장권을 자유 시장에 맡기는 것이다.","paragraph":0,"memberIds":["L11:4"],"topic":"\"그러니까 표를 시장에 맡기는 게 가장 좋은 방법이야.\""}]}]},"claimEdits":[{"start":17,"end":24,"before":"파는 것보다 ","after":""},{"start":33,"end":36,"before":"주는 ","after":"주는 것보다 시장에서 파는 "}],"progressiveComparison":true,"progressiveStep":4,"progressiveTotal":5,"progressiveLabel":"관계 파악","learningFocus":"높은 가격에 팔자는 이유","hintGuide":"최선의 방법이라고 제시한 것이 무엇인가요?","synthesis":false,"editorSourceVersion":"d1a435432f2bf4092cbf9c0bf44cdffcfbefc4acc038746f80dab39a8a3d067a"}]},{"name":"5단계 · 핵심 의미 확인","items":[{"id":"U22-H11-05-B1","type":"ox","changed":"시장을 지지하는 사람들은 표를 비싸게 사겠다는 사람이 공연을 가장 원한다고 본다. 그래서 표를 시장에서 팔게 하자고 제안한다.","answer":"O","ask":"다음 설명이 이 문단의 중요한 내용과 같으면 O, 다르면 X를 고르세요.","why":"공연을 가장 원하는 사람을 고르는 방법으로 그 사람이 내겠다는 돈을 보는 거예요. 그래서 가장 높은 가격을 내겠다는 사람에게 표가 가도록 팔자고 합니다. 이는 필자가 예상한 시장 옹호자의 생각이에요.\n근거: “그런데 그 사람은 바로 입장권에 최고 가격을 지불하는 사람들이다.” “따라서 공연에서 최대의 즐거움을 끌어낼 관객으로 극장을 채울 수 있는 최선의 방법은 입장권을 자유 시장에 맡기는 것이다.” “최고 가격을 자발적으로 지불하는 사람에게 입장권이 돌아가게 하는 것이 셰익스피어 공연의 가치를 가장 높게 평가하는 사람을 결정하는 최고의 방법이다.”","paragraphCount":1,"readingLabel":"11문단 · 핵심 읽기 5/5단계","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 11문단","passage":"[문단 전체 · 11문단]\n이러한 주장에 대해 자유 시장 옹호자들은 다음과 같은 반응을 보일 수 있다. 극장 측이 연극을 열렬하게 관람하고 싶어 하는 사람들로 관람석을 채우고 공연이 주는 즐거움을 극대화하고 싶다면, 그 가치를 가장 높게 평가하는 사람에게 입장권이 돌아가기를 원해야 한다. 그런데 그 사람은 바로 입장권에 최고 가격을 지불하는 사람들이다. 따라서 공연에서 최대의 즐거움을 끌어낼 관객으로 극장을 채울 수 있는 최선의 방법은 입장권을 자유 시장에 맡기는 것이다. 다시 말해 시장이 수용할 수 있는 가격이 얼마가 됐든 그 가격에 입장권을 판매하든지, 아니면 돈을 받고 대신 줄을 선 사람이나 암표상이 가장 높은 가격을 지불하려는 사람에게 입장권을 팔 수 있도록 허용하는 것이다. 최고 가격을 자발적으로 지불하는 사람에게 입장권이 돌아가게 하는 것이 셰익스피어 공연의 가치를 가장 높게 평가하는 사람을 결정하는 최고의 방법이다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"highlightEvidence":true,"originPage":"unit22","shortComparison":true,"focusQuotes":[{"id":"L11:3","text":"그런데 그 사람은 바로 입장권에 최고 가격을 지불하는 사람들이다."},{"id":"L11:4","text":"따라서 공연에서 최대의 즐거움을 끌어낼 관객으로 극장을 채울 수 있는 최선의 방법은 입장권을 자유 시장에 맡기는 것이다."},{"id":"L11:6","text":"최고 가격을 자발적으로 지불하는 사람에게 입장권이 돌아가게 하는 것이 셰익스피어 공연의 가치를 가장 높게 평가하는 사람을 결정하는 최고의 방법이다."}],"skills":["비교"],"evidence":{"title":"가격으로 관람 욕구 판단하기","statement":"시장을 지지하는 사람들은 표를 비싸게 사겠다는 사람이 공연을 가장 원한다고 본다. 그래서 표를 시장에서 팔게 하자고 제안한다.","explanation":"공연을 가장 원하는 사람을 고르는 방법으로 그 사람이 내겠다는 돈을 보는 거예요. 그래서 가장 높은 가격을 내겠다는 사람에게 표가 가도록 팔자고 합니다. 이는 필자가 예상한 시장 옹호자의 생각이에요.\n근거: “그런데 그 사람은 바로 입장권에 최고 가격을 지불하는 사람들이다.” “따라서 공연에서 최대의 즐거움을 끌어낼 관객으로 극장을 채울 수 있는 최선의 방법은 입장권을 자유 시장에 맡기는 것이다.” “최고 가격을 자발적으로 지불하는 사람에게 입장권이 돌아가게 하는 것이 셰익스피어 공연의 가치를 가장 높게 평가하는 사람을 결정하는 최고의 방법이다.”","valid":["L11:3","L11:4","L11:6"],"sources":[{"id":"L11","title":"줄 서기를 돈으로 살 수 있을까","label":"11문단","sentences":[{"id":"L11:1","text":"이러한 주장에 대해 자유 시장 옹호자들은 다음과 같은 반응을 보일 수 있다.","paragraph":0,"memberIds":["L11:1"],"topic":"“이러한 주장”은 앞 문단의 “암표 거래는 돈이 부족한 사람에게 불공정하다”는 주장이다. 이에 대해 자유 시장 옹호자들이 아래처럼 반론할 수 있다고 필자가 예상한다."},{"id":"L11:2","text":"극장 측이 연극을 열렬하게 관람하고 싶어 하는 사람들로 관람석을 채우고 공연이 주는 즐거움을 극대화하고 싶다면, 그 가치를 가장 높게 평가하는 사람에게 입장권이 돌아가기를 원해야 한다.","paragraph":0,"memberIds":["L11:2"],"topic":"\"극장은 정말 보고 싶은 사람들로 자리를 채우고 싶지? 공연의 즐거움을 최대로 하고 싶지? 그렇다면 공연을 가장 귀하게 여기는 사람에게 표가 가야 해.\""},{"id":"L11:3","text":"그런데 그 사람은 바로 입장권에 최고 가격을 지불하는 사람들이다.","paragraph":0,"memberIds":["L11:3"],"topic":"\"그 사람이 누구냐고? 바로 표에 가장 비싼 돈을 내는 사람이야.\""},{"id":"L11:4","text":"따라서 공연에서 최대의 즐거움을 끌어낼 관객으로 극장을 채울 수 있는 최선의 방법은 입장권을 자유 시장에 맡기는 것이다.","paragraph":0,"memberIds":["L11:4"],"topic":"\"그러니까 표를 시장에 맡기는 게 가장 좋은 방법이야.\""},{"id":"L11:5","text":"다시 말해 시장이 수용할 수 있는 가격이 얼마가 됐든 그 가격에 입장권을 판매하든지, 아니면 돈을 받고 대신 줄을 선 사람이나 암표상이 가장 높은 가격을 지불하려는 사람에게 입장권을 팔 수 있도록 허용하는 것이다.","paragraph":0,"memberIds":["L11:5"],"topic":"\"방법은 두 가지야. ㉠ 극장이 사람들이 낼 수 있는 만큼 값을 매겨 표를 팔거나, ㉡ 줄 알바나 암표상이 가장 비싸게 사려는 사람에게 팔게 내버려 두거나.\""},{"id":"L11:6","text":"최고 가격을 자발적으로 지불하는 사람에게 입장권이 돌아가게 하는 것이 셰익스피어 공연의 가치를 가장 높게 평가하는 사람을 결정하는 최고의 방법이다.","paragraph":0,"memberIds":["L11:6"],"topic":"\"스스로 가장 비싼 돈을 내는 사람에게 표를 주는 것, 그게 공연을 가장 좋아하는 사람을 고르는 최고의 방법이야.\""}]}]},"progressiveComparison":true,"progressiveStep":5,"progressiveTotal":5,"progressiveLabel":"핵심 의미 확인","learningFocus":"가격으로 관람 욕구 판단하기","hintGuide":"누가 공연을 가장 원하는지 판단하는 방법과 표를 팔자는 제안을 이어 보세요.","synthesis":true,"editorSourceVersion":"03206b5fb63b45daef1a1372205c7160d7982a0faa9a4bd19d1f9d9327990be3"},{"id":"U22-H11-05-B2","type":"ox","changed":"극장 대변인은 가장 비싼 값을 내겠다는 사람에게 표를 팔자고 주장한다.","answer":"X","ask":"다음 설명이 이 문단의 중요한 내용과 같으면 O, 다르면 X를 고르세요.","why":"가장 비싼 값을 내는 사람에게 표를 팔자는 말은 시장 옹호자들이 할 수 있는 반론이에요. 글쓴이가 그 반론을 예상해서 소개했으며, 극장 대변인의 말이라고 하지 않았어요.\n근거: “이러한 주장에 대해 자유 시장 옹호자들은 다음과 같은 반응을 보일 수 있다.” “최고 가격을 자발적으로 지불하는 사람에게 입장권이 돌아가게 하는 것이 셰익스피어 공연의 가치를 가장 높게 평가하는 사람을 결정하는 최고의 방법이다.”","paragraphCount":1,"readingLabel":"11문단 · 핵심 읽기 5/5단계","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 11문단","passage":"[문단 전체 · 11문단]\n이러한 주장에 대해 자유 시장 옹호자들은 다음과 같은 반응을 보일 수 있다. 극장 측이 연극을 열렬하게 관람하고 싶어 하는 사람들로 관람석을 채우고 공연이 주는 즐거움을 극대화하고 싶다면, 그 가치를 가장 높게 평가하는 사람에게 입장권이 돌아가기를 원해야 한다. 그런데 그 사람은 바로 입장권에 최고 가격을 지불하는 사람들이다. 따라서 공연에서 최대의 즐거움을 끌어낼 관객으로 극장을 채울 수 있는 최선의 방법은 입장권을 자유 시장에 맡기는 것이다. 다시 말해 시장이 수용할 수 있는 가격이 얼마가 됐든 그 가격에 입장권을 판매하든지, 아니면 돈을 받고 대신 줄을 선 사람이나 암표상이 가장 높은 가격을 지불하려는 사람에게 입장권을 팔 수 있도록 허용하는 것이다. 최고 가격을 자발적으로 지불하는 사람에게 입장권이 돌아가게 하는 것이 셰익스피어 공연의 가치를 가장 높게 평가하는 사람을 결정하는 최고의 방법이다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"highlightEvidence":true,"originPage":"unit22","shortComparison":true,"focusQuotes":[{"id":"L11:1","text":"이러한 주장에 대해 자유 시장 옹호자들은 다음과 같은 반응을 보일 수 있다."},{"id":"L11:6","text":"최고 가격을 자발적으로 지불하는 사람에게 입장권이 돌아가게 하는 것이 셰익스피어 공연의 가치를 가장 높게 평가하는 사람을 결정하는 최고의 방법이다."}],"skills":["주체"],"evidence":{"title":"누가 할 법한 말인가","statement":"시장 옹호자들은 가장 비싼 값을 내겠다는 사람에게 표를 팔자고 주장할 수 있다.","explanation":"가장 비싼 값을 내는 사람에게 표를 팔자는 말은 시장 옹호자들이 할 수 있는 반론이에요. 글쓴이가 그 반론을 예상해서 소개했으며, 극장 대변인의 말이라고 하지 않았어요.\n근거: “이러한 주장에 대해 자유 시장 옹호자들은 다음과 같은 반응을 보일 수 있다.” “최고 가격을 자발적으로 지불하는 사람에게 입장권이 돌아가게 하는 것이 셰익스피어 공연의 가치를 가장 높게 평가하는 사람을 결정하는 최고의 방법이다.”","valid":["L11:1","L11:6"],"sources":[{"id":"L11","title":"줄 서기를 돈으로 살 수 있을까","label":"11문단","sentences":[{"id":"L11:1","text":"이러한 주장에 대해 자유 시장 옹호자들은 다음과 같은 반응을 보일 수 있다.","paragraph":0,"memberIds":["L11:1"],"topic":"“이러한 주장”은 앞 문단의 “암표 거래는 돈이 부족한 사람에게 불공정하다”는 주장이다. 이에 대해 자유 시장 옹호자들이 아래처럼 반론할 수 있다고 필자가 예상한다."},{"id":"L11:2","text":"극장 측이 연극을 열렬하게 관람하고 싶어 하는 사람들로 관람석을 채우고 공연이 주는 즐거움을 극대화하고 싶다면, 그 가치를 가장 높게 평가하는 사람에게 입장권이 돌아가기를 원해야 한다.","paragraph":0,"memberIds":["L11:2"],"topic":"\"극장은 정말 보고 싶은 사람들로 자리를 채우고 싶지? 공연의 즐거움을 최대로 하고 싶지? 그렇다면 공연을 가장 귀하게 여기는 사람에게 표가 가야 해.\""},{"id":"L11:3","text":"그런데 그 사람은 바로 입장권에 최고 가격을 지불하는 사람들이다.","paragraph":0,"memberIds":["L11:3"],"topic":"\"그 사람이 누구냐고? 바로 표에 가장 비싼 돈을 내는 사람이야.\""},{"id":"L11:4","text":"따라서 공연에서 최대의 즐거움을 끌어낼 관객으로 극장을 채울 수 있는 최선의 방법은 입장권을 자유 시장에 맡기는 것이다.","paragraph":0,"memberIds":["L11:4"],"topic":"\"그러니까 표를 시장에 맡기는 게 가장 좋은 방법이야.\""},{"id":"L11:5","text":"다시 말해 시장이 수용할 수 있는 가격이 얼마가 됐든 그 가격에 입장권을 판매하든지, 아니면 돈을 받고 대신 줄을 선 사람이나 암표상이 가장 높은 가격을 지불하려는 사람에게 입장권을 팔 수 있도록 허용하는 것이다.","paragraph":0,"memberIds":["L11:5"],"topic":"\"방법은 두 가지야. ㉠ 극장이 사람들이 낼 수 있는 만큼 값을 매겨 표를 팔거나, ㉡ 줄 알바나 암표상이 가장 비싸게 사려는 사람에게 팔게 내버려 두거나.\""},{"id":"L11:6","text":"최고 가격을 자발적으로 지불하는 사람에게 입장권이 돌아가게 하는 것이 셰익스피어 공연의 가치를 가장 높게 평가하는 사람을 결정하는 최고의 방법이다.","paragraph":0,"memberIds":["L11:6"],"topic":"\"스스로 가장 비싼 돈을 내는 사람에게 표를 주는 것, 그게 공연을 가장 좋아하는 사람을 고르는 최고의 방법이야.\""}]}]},"claimEdits":[{"start":0,"end":8,"before":"극장 대변인은 ","after":"시장 옹호자들은 "},{"start":34,"end":39,"before":"주장한다.","after":"주장할 수 있다."}],"progressiveComparison":true,"progressiveStep":5,"progressiveTotal":5,"progressiveLabel":"핵심 의미 확인","learningFocus":"누가 할 법한 말인가","hintGuide":"첫 문장에서 앞으로 소개할 반응을 보일 수 있다고 한 사람들은 누구인가요?","synthesis":true,"editorSourceVersion":"6d9953cf712e72313fa17e817effffcc4783497a2458bdfcd0c920e158af4c1a"}]}],"resetReviewOnRevision":true,"shuffleWithinParts":true,"orderedProgression":true,"cat":"2-2단원"};})(window);
